1	/**
2	 * The MHPCO claim office: it settles a damage report against an open policy. It
3	 * answers what the office pays for a reported damage -- what the damage is worth
4	 * under the policy's clauses, and what the office's settlement conventions then
5	 * deduct from it. It knows nothing about what a policy costs to take out; that
6	 * is the quote's business.
7	 */
8	
9	import { insuranceValueOf, type Item } from "./price-list.js";
10	
11	export interface Damage {
12	  itemType: string;
13	  amount: number;
14	}
15	
16	export interface Incident {
17	  cause: string;
18	  damages: Damage[];
19	}
20	
21	export interface Policy {
22	  items: Item[];
23	  cap: number;
24	  /** What is left of the cap after the claims already paid on this policy. */
25	  remainingCap: number;
26	}
27	
28	export interface ClaimResult {
29	  payout: number;
30	  remainingCap: number;
31	}
32	
33	const CAP_MULTIPLE_OF_INSURANCE_SUM = 2;
34	
35	/** The sum a policy insures, read off the price list for the items it covers. */
36	export function insuranceSum(policy: Policy): number {
37	  return insuranceValueOf(policy.items);
38	}
39	
40	/**
41	 * Opening a policy fixes the cover it grants: the office caps its total payout at
42	 * twice the insurance sum of the items presented. The cap is fixed from the
43	 * items' own insurance values, so no premium modifier can raise it.
44	 */
45	export function openPolicy(items: Item[]): Policy {
46	  const cap = CAP_MULTIPLE_OF_INSURANCE_SUM * insuranceValueOf(items);
47	  return { items, cap, remainingCap: cap };
48	}
49	
50	const DEDUCTIBLE_PER_DAMAGE = 100;
51	
52	const HALF_REIMBURSEMENT_ENCHANTMENT_LEVEL = 8;
53	const HALF_REIMBURSEMENT_PERCENT = 50;
54	const PERCENT = 100;
55	
56	/**
57	 * The claim office's enchantment threshold, deliberately its own rule. The price
58	 * list also reads an enchantment level off an item, but for an unrelated purpose
59	 * and at an unrelated level (>= 5, a premium risk surcharge). The two thresholds
60	 * share no cause: moving one does not move the other, which is why the office
61	 * keeps them apart rather than naming them alike.
62	 */
63	function qualifiesForHalfReimbursement(item: Item): boolean {
64	  return (item.enchantment ?? 0) >= HALF_REIMBURSEMENT_ENCHANTMENT_LEVEL;
65	}
66	
67	/**
68	 * What a reported damage is worth under the policy's clauses. A deeply enchanted
69	 * item is reimbursed at half its damage; an item no clause speaks to is
70	 * reimbursed in full.
71	 *
72	 * The office also names a dragon-material clause, and it is deliberately absent
73	 * here rather than overlooked. That clause grants full reimbursement -- which is
74	 * already what an item no clause speaks to receives -- so it can only change an
75	 * outcome by overriding a *reducing* clause. Against the sole reducing clause the
76	 * office has, the half-reimbursement rule, it does not: a dragon-material sword
77	 * at enchantment 8 or 9 is valued at half, not in full. So under every rule the
78	 * office currently holds, a dragon branch would return exactly what this fallback
79	 * returns. Writing it would not encode the clause; it would encode a precedence
80	 * decision between dragon material and some future reducing clause, and the
81	 * office has not made that decision. When a reducing clause appears that dragon
82	 * material is meant to outrank, that precedence becomes observable and belongs
83	 * here then.
84	 */
85	function reimbursementFor(damage: Damage, item: Item): number {
86	  if (qualifiesForHalfReimbursement(item)) {
87	    return (damage.amount * HALF_REIMBURSEMENT_PERCENT) / PERCENT;
88	  }
89	  return damage.amount;
90	}
91	
92	/**
93	 * The insured items a policy has still to answer for in one incident. Each
94	 * reported damage claims one of them, so an incident can name an item only as
95	 * often as the policy actually covers it.
96	 */
97	function unclaimedItems(policy: Policy): Item[] {
98	  return [...policy.items];
99	}
100	
101	/**
102	 * The insured item a reported damage refers to, claimed from those the incident
103	 * has not spoken for yet, and matched on item type alone. A damage the office
104	 * can match to nothing is refused rather than settled -- it will not pay against
105	 * cover it never granted. An uninsured type, an unknown type, and one entry too
106	 * many of an insured type all meet the same refusal here, and deliberately so:
107	 * each names a damage to something this policy does not answer for. The price
108	 * list's separate refusal of unlisted types answers a different question -- what
109	 * the office is willing to insure at all.
110	 */
111	function claimDamagedItem(unclaimed: Item[], damage: Damage): Item {
112	  const index = unclaimed.findIndex((insured) => insured.type === damage.itemType);
113	  if (index === -1) {
114	    throw new Error(`The policy does not cover an item of type "${damage.itemType}"`);
115	  }
116	  return unclaimed.splice(index, 1)[0];
117	}
118	
119	/**
120	 * Settling turns a reimbursement into the sum actually paid. The deductible is
121	 * the MHPCO's settlement convention, not a clause: it is charged per damage
122	 * event, after the reimbursement is valued, and never turns a payout negative.
123	 */
124	function settleReimbursement(reimbursement: number): number {
125	  return Math.max(reimbursement - DEDUCTIBLE_PER_DAMAGE, 0);
126	}
127	
128	/**
129	 * A damage is a loss the office may be asked to make good, so it cannot be
130	 * negative: a negative amount is not a smaller claim but a nonsensical one, and
131	 * the office refuses it rather than reading it as no loss at all.
132	 */
133	function refuseNonsensicalAmount(damage: Damage): void {
134	  if (damage.amount < 0) {
135	    throw new Error(
136	      `A damage cannot be reported as a negative amount, but "${damage.itemType}" reports ${damage.amount}`,
137	    );
138	  }
139	}
140	
141	/**
142	 * The office's whole decision about one reported damage: refuse it if it is
143	 * nonsensical, claim the insured item it refers to, value it under the policy's
144	 * clauses, then settle that reimbursement. What the office then does with
145	 * several such sums -- adding them up and charging them against the policy's
146	 * remaining cap -- is the claim's business, not this one's.
147	 */
148	function settleDamage(unclaimed: Item[], damage: Damage): number {
149	  refuseNonsensicalAmount(damage);
150	  return settleReimbursement(reimbursementFor(damage, claimDamagedItem(unclaimed, damage)));
151	}
152	
153	/**
154	 * What the office would pay for an incident on the strength of its damages
155	 * alone: every reported damage settled under the policy's clauses, added up.
156	 * This is what the claim *desires* to pay -- a separate question from what the
157	 * policy's remaining cover then permits it to actually pay.
158	 */
159	function desiredPayout(policy: Policy, incident: Incident): number {
160	  const unclaimed = unclaimedItems(policy);
161	  return incident.damages.reduce((total, damage) => total + settleDamage(unclaimed, damage), 0);
162	}
163	
164	/**
165	 * The cover side of the office's ledger, the counterpart of `openPolicy`: what
166	 * the policy actually permits the office to pay towards a desired sum, and what
167	 * that leaves. A claim may draw no more than the cover still standing, so a
168	 * desire that would exceed it is reduced to whatever remains; what is drawn is
169	 * then gone from the policy for good.
170	 *
171	 * This is where the office's cap rule is revised -- a per-incident sub-cap or a
172	 * cover that reinstates would change this line and `openPolicy`, and nothing
173	 * about how a damage is valued or settled.
174	 */
175	function drawDownCover(policy: Policy, desired: number): number {
176	  const drawn = Math.min(desired, policy.remainingCap);
177	  policy.remainingCap -= drawn;
178	  return drawn;
179	}
180	
181	/**
182	 * MHPCO rounds a payout down: every fraction of a G it would owe stays in the
183	 * office's coffers. Only the final payout is rounded -- the clause valuations and
184	 * the deductible before it are kept as exact fractions -- and it is rounded before
185	 * the cover is drawn, so the cap is only ever charged what the office actually pays.
186	 *
187	 * This is the paying side of the office's single rounding principle; the quote
188	 * holds the collecting side and rounds the other way. The shared principle is a
189	 * direction ("in the MHPCO's favor"), not a shared calculation: the direction is
190	 * fixed by which way the money moves, so there is nothing for the two sides to
191	 * share but the phrase. They are revised independently.
192	 */
193	function roundPayoutInMHPCOsFavor(payout: number): number {
194	  return Math.floor(payout);
195	}
196	
197	/**
198	 * The office pays what the incident's damages come to, so far as the policy's
199	 * remaining cover permits.
200	 */
201	export function claim(policy: Policy, incident: Incident): ClaimResult {
202	  const payout = drawDownCover(
203	    policy,
204	    roundPayoutInMHPCOsFavor(desiredPayout(policy, incident)),
205	  );
206	  return { payout, remainingCap: policy.remainingCap };
207	}
208

1	/**
2	 * The claim-office counter: it takes a scenario in at the window, walks the
3	 * customer's steps past the office's clerks in order, and writes back what each
4	 * step came to. It translates between JSON and the office's own vocabulary and
5	 * decides nothing about premiums or payouts itself.
6	 */
7	
8	import { readFileSync } from "node:fs";
9	
10	import { quote, type Customer } from "./quote.js";
11	import { type Item } from "./price-list.js";
12	import { claim, openPolicy, type Incident, type Policy } from "./claim.js";
13	
14	interface QuoteStep {
15	  op: "quote";
16	  items: Item[];
17	}
18	
19	interface ClaimStep {
20	  op: "claim";
21	  policy: number;
22	  incident: Incident;
23	}
24	
25	type Step = QuoteStep | ClaimStep;
26	
27	interface Scenario {
28	  customer: Customer;
29	  steps: Step[];
30	}
31	
32	/**
33	 * What the counter writes back for one step, in the wire's own vocabulary. The
34	 * claim arm lists the same two figures a `ClaimResult` carries, and deliberately
35	 * is not that type: the office's answer and the shape the wire promises are
36	 * different knowledge that happen to coincide today. The counter therefore names
37	 * the fields it puts on stdout rather than passing the office's answer through,
38	 * so that a figure the office one day adds for its own purposes -- a per-clause
39	 * breakdown, say -- does not silently become part of what the CLI promises.
40	 */
41	type StepResult = { premium: number } | { payout: number; remainingCap: number };
42	
43	/** The scenario arrives on stdin as one JSON document. */
44	function readStdin(): string {
45	  return readFileSync(0, "utf8");
46	}
47	
48	/**
49	 * Walks the customer's steps past the office in the order they were presented.
50	 * A quote step takes out a policy, which the office keeps against the step that
51	 * created it so that a later claim step can name it; a claim step is settled
52	 * against that policy, drawing on cover any earlier claim on it has left.
53	 *
54	 * The office also counts the contracts the customer has taken out as the walk
55	 * goes on, because every quote after the first is a follow-up contract and is
56	 * discounted as one.
57	 */
58	function runScenario(scenario: Scenario): StepResult[] {
59	  const policiesByStep = new Map<number, Policy>();
60	  const results: StepResult[] = [];
61	  let contractsTakenOut = 0;
62	
63	  scenario.steps.forEach((step, stepIndex) => {
64	    if (step.op === "quote") {
65	      policiesByStep.set(stepIndex, openPolicy(step.items));
66	      results.push({ premium: quote(scenario.customer, step.items, contractsTakenOut) });
67	      contractsTakenOut += 1;
68	      return;
69	    }
70	    const settlement = claim(policyOfStep(policiesByStep, step.policy), step.incident);
71	    results.push({ payout: settlement.payout, remainingCap: settlement.remainingCap });
72	  });
73	
74	  return results;
75	}
76	
77	/** The policy a claim step names, by the index of the quote step that opened it. */
78	function policyOfStep(policiesByStep: Map<number, Policy>, stepIndex: number): Policy {
79	  const policy = policiesByStep.get(stepIndex);
80	  if (policy === undefined) {
81	    throw new Error(`Step ${stepIndex} did not take out a policy to claim against`);
82	  }
83	  return policy;
84	}
85	
86	const REFUSED = 1;
87	
88	/**
89	 * How the counter turns the office away at the window. A refusal is a
90	 * description of what is wrong, not a crash report: the customer is told the
91	 * office's own reason and nothing of the machinery that raised it, which is why
92	 * only the message is written and never a stack trace. Nothing is paid, so
93	 * stdout stays empty and the status is non-zero.
94	 *
95	 * This is the shape of a refusal, and the only place it is decided. Which
96	 * conditions are worth refusing is not settled here at all -- the price list and
97	 * the claim office each refuse on their own grounds, and every one of them
98	 * arrives at this one window and is reported the same way.
99	 */
100	function refuse(refusal: Error): never {
101	  process.stderr.write(`${refusal.message}\n`);
102	  process.exit(REFUSED);
103	}
104	
105	/**
106	 * The counter's day: read the scenario presented at the window, walk it past the
107	 * office, and write back what it came to. The results are written only once the
108	 * whole scenario has gone through, so a scenario refused part-way leaves no
109	 * half-finished answer behind it.
110	 */
111	function main(): void {
112	  const scenario = JSON.parse(readStdin()) as Scenario;
113	  const results = runScenario(scenario);
114	  process.stdout.write(JSON.stringify({ results }) + "\n");
115	}
116	
117	try {
118	  main();
119	} catch (refusal) {
120	  refuse(refusal as Error);
121	}
122

1	import { describe, expect, it } from "vitest";
2	import { policyBasePremium, quote } from "./quote.js";
3	import { claim, insuranceSum, openPolicy } from "./claim.js";
4	import { execFileSync } from "node:child_process";
5	
6	interface CliRun {
7	  status: number;
8	  stdout: string;
9	  stderr: string;
10	}
11	
12	function runCli(scenario: unknown): CliRun {
13	  try {
14	    const stdout = execFileSync("npx", ["tsx", "src/cli.ts"], {
15	      input: JSON.stringify(scenario),
